"""Built-in, authored practice material. Never presented as AI personalization."""
from .db import digest, now, put


TECHNICAL = [
    ('Core Technical Fundamentals', 'How do you choose what to test first?', 'Rank risks by impact and likelihood. Start with critical user journeys, recently changed integrations, security boundaries and known failure areas. Use production incidents and usage data to refine the order; record what remains untested and why.'),
    ('Programming and Coding', 'How would you remove duplicates while preserving input order?', 'Track seen values in a set and append unseen values to an output list. This takes expected O(n) time and O(n) extra space for hashable values. Define equality and handling for nulls and unhashable values before coding. Test empty input, repeated values and already unique input.'),
    ('Frameworks and Tools', 'What makes an automation framework maintainable?', 'Separate business intent from transport and UI details. Centralize configuration, fixtures, selectors and reporting. Keep tests independent and deterministic, use explicit synchronization, and expose diagnostic logs. Review flaky tests as defects instead of increasing retries until they pass.'),
    ('Technical Scenarios', 'A test passes locally but fails in CI. How do you investigate?', 'Compare runtime versions, environment variables, timezone, network access, test data and resource limits. Reproduce with the same command and seed. Check shared state and parallel execution. Capture logs or traces, isolate the smallest failing case, then verify the fix under repeated CI conditions.'),
    ('System Design and Architecture', 'How would you test an asynchronous distributed workflow?', 'Test each service contract and the end-to-end state transition. Exercise duplicate messages, retries, out-of-order delivery, timeouts and partial outages. Verify idempotency, eventual consistency and reconciliation. Correlate events with trace IDs and measure convergence against an explicit deadline.'),
    ('Resume-Based Technical Deep Dives', 'How should you explain a technical achievement from your resume?', 'Choose an achievement explicitly recorded in the resume. Explain the starting problem, your individual contribution, the alternatives considered, the implementation and the evidence of the result. Distinguish your work from team outcomes. Use only recorded metrics and say when a measurement is unavailable.'),
    ('Advanced Debugging', 'How do you find the cause of intermittent production failures?', 'Establish the affected requests and timeline, correlate logs, metrics and traces, and compare successful and failing cases. Form a falsifiable hypothesis about shared state, timing, dependencies or resource pressure. Reproduce or instrument it, change one factor, then verify both the symptom and the causal mechanism.'),
    ('Database and SQL', 'How do you find duplicate non-null email addresses in a users table?', 'Use SELECT email, COUNT(*) AS occurrences FROM users WHERE email IS NOT NULL GROUP BY email HAVING COUNT(*) > 1. Decide whether case and whitespace should be normalized before grouping. Verify empty tables, unique addresses, duplicates and null values. Add an appropriate uniqueness constraint only after resolving existing duplicates.'),
    ('API and Backend Engineering', 'What should an API test cover beyond a successful status code?', 'Check response schema and business invariants, persistence and emitted events, authentication, authorization and tenant boundaries. Exercise invalid inputs, rate limits, pagination, concurrency and dependency failures. For writes, verify retries are idempotent and that rejected requests produce no unintended side effects.'),
    ('Technical Leadership', 'How do you decide whether a release is ready?', 'Review critical defects, risk coverage, changed integrations, observability, rollback readiness and unresolved unknowns. Present evidence and business impact to accountable stakeholders. Define release gates before the deadline, document exceptions, and assign monitoring and rollback owners.'),
    ('Domain-Specific Questions', 'How do you discover domain rules before designing tests?', 'Trace an actual user journey with domain experts. Identify invariants, state transitions, permissions and external dependencies. Translate examples and counterexamples into acceptance criteria. Clarify ambiguous rules rather than treating current behavior as the specification.'),
    ('AI and Emerging Technologies', 'How do you validate an LLM-assisted system?', 'Use an evidence-labelled evaluation set and measure task success, groundedness and failure handling. Test prompt injection, missing context and unsupported claims. Evaluate retrieval separately from generation, track latency and cost, and require human review where errors have material consequences.'),
]

HR = [
    ('Tell Me About Yourself', 'How should you structure your introduction?', 'Use a present-past-future structure: your current role, two relevant strengths supported by actual work, and why the advertised role is a logical next step. Aim for 60–90 seconds. Replace general adjectives with one supported example; do not add unverified experience.'),
    ('Why Do You Want to Work With Us?', 'How do you explain your interest in this role?', 'Connect two explicit responsibilities in the JD with skills or experience you can substantiate. Explain what you want to contribute and learn. Treat company culture or product claims as unknown unless you have checked reliable company information.'),
    ('Notice Period', 'How should you answer a notice-period question?', 'State your actual contractual notice period and any confirmed last working date. If an earlier release is uncertain, describe it as subject to employer agreement. Do not promise an immediate start without confirmation.'),
    ('Salary Expectations', 'How do you discuss salary without inventing a number?', 'Ask for the budgeted range and clarify level, location and total compensation. Share a researched range only after checking relevant market evidence and your own requirements. If no range is available, say you would like to understand the scope before agreeing on compensation.'),
    ('Do You Have Any Questions for Me?', 'What should you ask at the end of an interview?', 'Ask how success will be measured in the first months, what the team’s most important current challenge is, and how the role collaborates with key partners. Choose one to three questions that have not already been answered.'),
    ('Career Background and Motivation', 'How do you explain a career transition?', 'Describe the actual reason briefly and respectfully, then connect your existing skills with the new role’s responsibilities. Address any genuine gap with a specific learning plan. Avoid blaming previous colleagues or fabricating a career narrative.'),
    ('Strengths and Weaknesses', 'How do you give a credible weakness answer?', 'Choose a real, relevant development area that you can discuss honestly. Explain its impact, the action you are taking and what evidence shows progress. Avoid disguised strengths or claiming that the issue has disappeared without evidence.'),
    ('Behavioral and Competency-Based', 'How do you answer a behavioral question using STAR?', 'Describe the Situation and Task briefly, spend most of the answer on your individual Actions, then explain the Result and what you learned. Use an actual event. If you have not faced the situation, say so and clearly label a proposed approach as hypothetical.'),
    ('Leadership and Management', 'How do you describe resolving a team conflict?', 'Use a real example: identify the underlying disagreement, explain how you listened to each party, establish a shared objective and describe the decision process. Separate facts from opinions and explain the actual outcome and follow-up.'),
    ('Work Culture and Collaboration', 'How do you collaborate across teams?', 'Agree on goals, responsibilities and working agreements early. Document decisions, raise dependencies with clear owners, and adapt communication to the audience. Support the answer with an actual example and explain how feedback changed your approach.'),
    ('Company and Role-Specific', 'How would you approach your first 90 days?', 'First understand the product, people and success measures. Next assess the highest-priority risks and deliver a small, validated improvement. Then agree on a measurable longer-term plan. Label this as a proposed plan and adapt it to the employer’s actual priorities.'),
    ('Difficult and Tricky HR', 'How do you explain a past failure?', 'Choose an actual event, accept responsibility for your contribution, and explain the impact without exposing confidential information. Describe the corrective action and the change that prevents recurrence. Do not reframe every failure as an unqualified success.'),
    ('International and Relocation', 'How do you discuss relocation and work authorization?', 'State your actual location, willingness to relocate, work authorization and any sponsorship requirement separately. Ask whether the employer supports the relevant process. Do not treat a relocation preference or a job advertisement as proof of visa eligibility.'),
    ('Career Goals', 'How do you describe your career goals?', 'Connect the work you want to become better at with the responsibilities of the role. Explain a realistic learning and contribution path. Avoid promising a title or promotion timeline that the employer has not offered.'),
    ('Final HR and Offers', 'What should you clarify before accepting an offer?', 'Review responsibilities, reporting line, location, compensation, benefits, notice, start date and any contingencies in writing. Ask about unclear terms and allow time to assess them. Express interest without claiming acceptance until you have made that decision.'),
]


def starter_guide(db, user_id, payload, candidate, version, error):
    kind=payload['kind']
    questions=[]
    for index,(category,question,answer) in enumerate(TECHNICAL if kind=='technical' else HR,1):
        questions.append({'id':f'PRACTICE-{index:03d}','category':category,'question':question,
                          'difficulty':'Foundational','priority':index,'interview_round':'Practice',
                          'source_classification':'General Preparation','short_answer':answer,
                          'detailed_answer':answer,'preparation_note':'Built-in answer guidance; adapt using your verified experience.'})
    data={'kind':kind,'questions':questions,'company':payload.get('company',''),'jd':payload['jd'],
          'resume_version_id':version,'generation_mode':'built_in','generation_status':'failed',
          'generation_error':error,'candidate_summary':candidate.get('designation',''),
          'top_question_ids':[q['id'] for q in questions], 'plans':{},'mock_interviews':[],
          'created_at':now().isoformat(),'validation_status':'needs_review'}
    key='practice:'+digest(str([kind,version,payload['jd'],payload.get('company','')]))
    row=put(db,user_id,'interview',key,data)
    db.commit()
    return {'content_id':row.id,'questions':len(questions),'built_in':True}
